repo_base = repo_local_path.resolve()
for watch_file in watch_files:
    if '\x00' in str(watch_file):
        raise ValueError(f'Null byte in watch_file path: {watch_file}')
    resolved = (repo_local_path / watch_file).resolve()
    if not resolved.is_relative_to(repo_base):
        raise ValueError(
            f'Watch file path escapes repo directory: {watch_file} '
            f'(resolved to {resolved}, repo base is {repo_base})'
        )
